from pathlib import Path
import base64, hashlib, subprocess, sys, zlib

root = Path(sys.argv[1]).resolve()
payload = ""
patch = zlib.decompress(base64.b64decode(payload))
expected = "ea15350fde3da66ea0c3403f757127651539160749bdd35aa0510c908b4d212e"
actual = hashlib.sha256(patch).hexdigest()
if actual != expected:
    raise RuntimeError(f"alpha45 patch checksum mismatch: {actual} != {expected}")

subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha45 achievements, difficulty rewards, filters, and Essentials dex persistence applied")
